function openHow(id){const g=id==='badminton-focused'?{name:'Badminton Focused',how:'Choose a game and unlocked tier. Every game rewards accurate information use, decision quality and correct timing rather than speed alone. Auto-Next and Full Screen are available throughout.'}:GAMES.find(x=>x.id===id);if(!g)return;const m=ensureModal();byId('gamesModalTitle').textContent=`${g.name} — How To Play`;byId('gamesModalBody').innerHTML=`<p>${escapeHtml(g.how)}</p><p><strong>What the score means:</strong> accuracy, timing, premature commitment and recovery quality are tracked according to the task.</p>`;m.hidden=false;document.body.classList.add('games-modal-open');}
