function playerGlyph(name,{colour='#d5ad5f',label='YOU',lean=0,racket=18}={}){const [x,y]=zonePoint(name);return `<g transform="translate(${x} ${y}) rotate(${lean})"><circle cy="-22" r="9" fill="#efc39b" stroke="#f3ead4" stroke-width="2"/><path d="M-11-12Q0-20 12-11L9 17Q0 24-10 16Z" fill="${colour}" stroke="#153d44" stroke-width="2"/><path d="M-5 16l-12 25M6 17l14 23M-8-5l-19 12M8-5l20-17" fill="none" stroke="#153d44" stroke-width="7" stroke-linecap="round"/><g transform="translate(27 -22) rotate(${racket})"><path d="M0 0l18-24" stroke="#f3ead4" stroke-width="3.5"/><ellipse cx="22" cy="-30" rx="8" ry="12" fill="none" stroke="#f3ead4" stroke-width="3.5"/></g><rect x="-23" y="43" width="46" height="17" rx="8.5" fill="#153d44" opacity=".9"/><text y="55" text-anchor="middle" font-family="Arial" font-size="10" font-weight="900" fill="#f3ead4">${label}</text></g>`;}
function movementArrow(from,to,colour='#d5ad5f',dash=''){const [x1,y1]=zonePoint(from),[x2,y2]=zonePoint(to);return `<path d="M${x1} ${y1} Q${(x1+x2)/2+18} ${(y1+y2)/2-18} ${x2} ${y2}" fill="none" stroke="${colour}" stroke-width="7" stroke-linecap="round" ${dash?`stroke-dasharray="${dash}"`:''} marker-end="url(#badArrow)"/>`;}
